//! Sample game: one mesh per reference material from `shaders/`, generated by shader-editor.
//!
//! Run with `cargo run` inside `examples/sample_game`; edit graphs in the editor while it runs —
//! Bevy's file watcher hot-reloads the regenerated `.wesl` files.

use bevy::prelude::*;
use bevy::sprite_render::SpriteMaterial;
use shaders::{CoordsMaterial, CurveBandsMaterial, DissolveMaterial, GlobalTintMaterial, Exp42Ext, Exp42Material, FlagExt, FlagMaterial, HologramMaterial, RockWetExt, RockWetMaterial, WaterExt, WaterMaterial};

fn main() {
    App::new()
        .add_plugins(DefaultPlugins.set(WindowPlugin {
            primary_window: Some(Window { title: "shader-editor sample".into(), ..default() }),
            ..default()
        }))
        .add_plugins(shaders::ShadersPlugin)
        .add_systems(Startup, setup)
        .add_systems(Update, (rotate, screenshot_and_exit))
        .run();
}

/// `SAMPLE_SCREENSHOT=out cargo run` saves `out-1.png` after a few seconds and `out-2.png` later,
/// then exits (checks the reference materials and hot reload without watching the window).
fn screenshot_and_exit(mut frames: Local<u32>, mut commands: Commands, mut exit: MessageWriter<AppExit>) {
    use bevy::render::view::screenshot::{Screenshot, save_to_disk};
    let Ok(path) = std::env::var("SAMPLE_SCREENSHOT") else { return };
    *frames += 1;
    for (i, at) in [(1, 300), (2, 900)] {
        if *frames == at {
            commands.spawn(Screenshot::primary_window()).observe(save_to_disk(format!("{path}-{i}.png")));
        }
    }
    if *frames == 960 {
        exit.write(AppExit::Success);
    }
}

#[derive(Component)]
struct Spin;

#[allow(clippy::too_many_arguments)]
fn setup(
    mut commands: Commands,
    assets: Res<AssetServer>,
    mut meshes: ResMut<Assets<Mesh>>,
    mut rock: ResMut<Assets<RockWetMaterial>>,
    mut exp: ResMut<Assets<Exp42Material>>,
    mut water: ResMut<Assets<WaterMaterial>>,
    mut flag: ResMut<Assets<FlagMaterial>>,
    mut hologram: ResMut<Assets<HologramMaterial>>,
    mut coords: ResMut<Assets<CoordsMaterial>>,
    mut dissolve: ResMut<Assets<DissolveMaterial>>,
    mut curve_bands: ResMut<Assets<CurveBandsMaterial>>,
    mut global_tint: ResMut<Assets<GlobalTintMaterial>>,
) {
    commands.spawn((Camera3d::default(), Transform::from_xyz(0.0, 3.0, 9.0).looking_at(Vec3::new(0.0, 0.5, 0.0), Vec3::Y)));
    commands.spawn((
        Camera2d,
        Camera { order: 1, clear_color: ClearColorConfig::None, ..default() },
    ));
    commands.spawn((
        DirectionalLight { illuminance: 8000.0, shadow_maps_enabled: true, ..default() },
        Transform::from_xyz(4.0, 8.0, 4.0).looking_at(Vec3::ZERO, Vec3::Y),
    ));

    let sphere = meshes.add(Sphere::new(1.0).mesh().uv(48, 24).with_generated_tangents().expect("tangents"));
    let rock_mat = RockWetExt::new(
        assets.load("textures/rock_albedo.png"),
        assets.load("textures/rock_normal.png"),
        LinearRgba::WHITE,
        0.4,
        1.5,
    );
    let exp_mat = Exp42Ext::new();

    commands.spawn((Mesh3d(sphere.clone()), MeshMaterial3d(rock.add(rock_mat.material())), Transform::from_xyz(-3.5, 1.0, 0.0), Spin));
    commands.spawn((Mesh3d(sphere.clone()), MeshMaterial3d(exp.add(exp_mat.material())), Transform::from_xyz(0.0, 1.0, 0.0), Spin));

    let plane = meshes.add(Plane3d::default().mesh().size(4.0, 4.0).build().with_generated_tangents().expect("tangents"));
    let water_mat = WaterExt::new(assets.load("textures/water_normal.png"), LinearRgba::rgb(0.0, 0.15, 0.3));
    commands.spawn((Mesh3d(plane), MeshMaterial3d(water.add(water_mat.material())), Transform::from_xyz(0.0, 0.0, 0.0)));

    let cloth = meshes.add(Plane3d::new(Vec3::Z, Vec2::new(1.0, 0.6)).mesh().subdivisions(24).build());
    commands.spawn((
        Mesh3d(cloth),
        MeshMaterial3d(flag.add(FlagExt::new(LinearRgba::rgb(0.8, 0.1, 0.1), 0.25).material())),
        Transform::from_xyz(3.0, 1.5, 0.0),
    ));

    commands.spawn((
        Mesh3d(meshes.add(Cylinder::new(0.6, 1.6))),
        MeshMaterial3d(hologram.add(HologramMaterial::new(LinearRgba::rgb(0.2, 0.8, 1.0), 0.5))),
        Transform::from_xyz(0.0, 1.2, -2.0),
    ));

    commands.spawn((
        Mesh3d(meshes.add(Cuboid::new(1.0, 1.0, 1.0))),
        MeshMaterial3d(coords.add(CoordsMaterial::new(assets.load("textures/atlas.png")))),
        Transform::from_xyz(0.0, 2.8, 0.0),
        Spin,
    ));

    // Bands shaped by the curve assets `common/pulse` and `common/steps`.
    commands.spawn((
        Mesh3d(meshes.add(Plane3d::new(Vec3::Z, Vec2::new(0.9, 0.6)).mesh().build())),
        MeshMaterial3d(curve_bands.add(CurveBandsMaterial::new())),
        Transform::from_xyz(3.3, 3.3, 0.0),
    ));

    // Colors, stripes and the striped branch come from the global constants of `common/tuning`.
    commands.spawn((
        Mesh3d(meshes.add(Plane3d::new(Vec3::Z, Vec2::new(0.9, 0.6)).mesh().build())),
        MeshMaterial3d(global_tint.add(GlobalTintMaterial::new())),
        Transform::from_xyz(-3.3, 3.3, 0.0),
    ));

    commands.spawn((
        Sprite::from_image(assets.load("textures/sprite.png")),
        SpriteMaterial(dissolve.add(DissolveMaterial::new(0.35, LinearRgba::rgb(1.0, 0.6, 0.1), 0.06))),
        Transform::from_xyz(-500.0, 250.0, 0.0).with_scale(Vec3::splat(2.0)),
    ));
}

fn rotate(time: Res<Time>, mut q: Query<&mut Transform, With<Spin>>) {
    for mut t in &mut q {
        t.rotate_y(time.delta_secs() * 0.4);
    }
}
